def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    return log1p(v)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0 or not sites:
            return 0.0
        volume = v * len(sites)
    total = 0.0
    for site in sites:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        o = site.get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if r is not None and r > 0:
            total += o * r ** 3
    return float(4.0 * pi * total / (3.0 * volume))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    if not n:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [float((props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    nearest = [inf] * n
    for edge in s.get('neighbors') or []:
        i, j = edge.get('i', -1), edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    values = [v for v in nearest if isfinite(v)]
    return float(sum(values) / len(values)) if values else 0.0

