def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    r = [float((props.get(e) or {}).get('covalent_radius_A') or 0.0) for e in elements]
    o = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total, unlike = 0.0, 0.0
    for edge in s.get('neighbors') or []:
        i, j = edge.get('i', -1), edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and r[i] > 0 and r[j] > 0:
            x = d / (r[i] + r[j])
            if x < 2.0:
                w = o[i] * o[j] * exp(-(x / 1.15) ** 6)
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    return float(unlike / total) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    p = [props.get(t.get('element')) or {} for t in sites]
    r = [float(t.get('covalent_radius_A') or 0.0) for t in p]
    en = [t.get('eneg') for t in p]
    o = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total, moment = 0.0, 0.0
    for edge in s.get('neighbors') or []:
        i, j = edge.get('i', -1), edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and r[i] > 0 and r[j] > 0 and en[i] is not None and en[j] is not None:
            x = d / (r[i] + r[j])
            if x < 2.0:
                w = o[i] * o[j] * exp(-(x / 1.15) ** 6)
                total += w
                moment += w * (en[i] - en[j]) ** 2
    return float(sqrt(moment / total)) if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    count, first, second = [0] * n, [0.0] * n, [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and 0 < d <= 1.25 * nearest[i]:
            count[i] += 1
            first[i] += d
            second[i] += d * d
    values = []
    for i in range(n):
        if count[i] > 0:
            mean = first[i] / count[i]
            values.append(sqrt(max(0.0, second[i] / count[i] - mean * mean)) / mean)
    return float(sum(values) / len(values)) if values else 0.0

