def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [float((props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    o = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    bonded = [False] * n
    for edge in s.get('neighbors') or []:
        i, j = edge.get('i', -1), edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and r[i] > 0 and r[j] > 0 and o[j] > 0:
            if d <= 1.25 * (r[i] + r[j]):
                bonded[i] = True
    den = sum(o[i] for i in range(n) if r[i] > 0)
    isolated = sum(o[i] for i in range(n) if r[i] > 0 and not bonded[i])
    return float(isolated / den) if den > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    selected = [t.get('element') in ('C', 'N') for t in sites]
    r = [float((props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    o = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    den = sum(o[i] for i in range(n) if selected[i] and r[i] > 0)
    if den <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i, j = edge.get('i', -1), edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and selected[i] and selected[j] and r[i] > 0 and r[j] > 0 and d is not None and 0 < d <= 1.25 * (r[i] + r[j]):
            total += o[i] * o[j]
    return float(total / den)

