def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    if not n:
        return 0.0
    props = s.get('element_properties') or {}
    r = [float((props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    o = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    labels = list(range(n))
    for edge in s.get('neighbors') or []:
        i, j = edge.get('i', -1), edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and i != j and o[i] > 0 and o[j] > 0 and r[i] > 0 and r[j] > 0 and d is not None and 0 < d <= 1.25 * (r[i] + r[j]):
            a, b = labels[i], labels[j]
            if a != b:
                for k in range(n):
                    if labels[k] == b:
                        labels[k] = a
    masses = {}
    for i in range(n):
        masses[labels[i]] = masses.get(labels[i], 0.0) + o[i]
    den = sum(o)
    return float(max(masses.values()) / den) if den > 0 else 0.0
